solution:
function sortByKeys(arr, keys) {
  const withIndex = arr.map((item, index) => ({ item, index }));
  withIndex.sort((a, b) => {
    for (const keySpec of keys) {
      const descending = keySpec.startsWith('-');
      const key = descending ? keySpec.slice(1) : keySpec;
      if (a.item[key] < b.item[key]) return descending ? 1 : -1;
      if (a.item[key] > b.item[key]) return descending ? -1 : 1;
    }
    return a.index - b.index;
  });
  return withIndex.map((entry) => entry.item);
}

