function createEventEmitter() {
  const listeners = {};
  return {
    on(event, handler) {
      if (!listeners[event]) {
        listeners[event] = [];
      }
      listeners[event].push(handler);
      return this;
    },
    off(event, handler) {
      if (!listeners[event]) {
        return this;
      }
      listeners[event] = listeners[event].filter((h) => h !== handler);
      return this;
    },
    emit(event, ...args) {
      if (!listeners[event]) {
        return false;
      }
      listeners[event].slice().forEach((handler) => handler(...args));
      return true;
    }
  };
}

