function createPubSub() {
  const topics = {};

  function unsubscribe(topic, handler) {
    if (!topics[topic]) {
      return;
    }
    topics[topic] = topics[topic].filter((h) => h !== handler);
  }

  return {
    subscribe(topic, handler) {
      if (!topics[topic]) {
        topics[topic] = [];
      }
      topics[topic].push(handler);
      return () => unsubscribe(topic, handler);
    },
    unsubscribe,
    publish(topic, data) {
      if (!topics[topic]) {
        return;
      }
      topics[topic].slice().forEach((handler) => handler(data));
    }
  };
}

