function immutableUpdate(obj, path, value) {
  const keys = path.split('.');

  function updateAt(current, index) {
    const key = keys[index];
    const isArrayLevel = Array.isArray(current);
    const clone = isArrayLevel ? current.slice() : { ...current };
    if (index === keys.length - 1) {
      clone[key] = value;
    } else {
      clone[key] = updateAt(current[key] || {}, index + 1);
    }
    return clone;
  }

  return updateAt(obj, 0);
}

