function traverseTree(root) {
  const dfsResult = [];
  const bfsResult = [];

  function walkDepthFirst(node) {
    if (!node) {
      return;
    }
    dfsResult.push(node.id);
    (node.children || []).forEach(walkDepthFirst);
  }
  walkDepthFirst(root);

  const queue = root ? [root] : [];
  while (queue.length > 0) {
    const node = queue.shift();
    bfsResult.push(node.id);
    (node.children || []).forEach((child) => queue.push(child));
  }

  return { dfs: dfsResult, bfs: bfsResult };
}

