function buildTree(records) {
  const nodesById = new Map();
  records.forEach((record) => {
    nodesById.set(record.id, { ...record, children: [] });
  });

  const roots = [];
  records.forEach((record) => {
    const node = nodesById.get(record.id);
    const hasParent = record.parentId !== null && record.parentId !== undefined && nodesById.has(record.parentId);
    if (hasParent) {
      nodesById.get(record.parentId).children.push(node);
    } else {
      roots.push(node);
    }
  });

  return roots;
}

