solution:
function createLRUCache(capacity) {
  const store = new Map();

  return {
    get(key) {
      if (!store.has(key)) {
        return -1;
      }
      const value = store.get(key);
      store.delete(key);
      store.set(key, value);
      return value;
    },
    put(key, value) {
      if (store.has(key)) {
        store.delete(key);
      } else if (store.size >= capacity) {
        const leastRecentlyUsedKey = store.keys().next().value;
        store.delete(leastRecentlyUsedKey);
      }
      store.set(key, value);
    }
  };
}

