function queryPipeline(data, config = {}) {
  let result = data.slice();
  const { searchTerm, searchKeys = [], filters = {}, sortKey, sortOrder = 'asc' } = config;

  Object.keys(filters).forEach((key) => {
    const filterValue = filters[key];
    result = result.filter((item) => item[key] === filterValue);
  });

  if (searchTerm) {
    const term = searchTerm.toLowerCase();
    result = result.filter((item) =>
      searchKeys.some((key) => String(item[key] == null ? '' : item[key]).toLowerCase().includes(term))
    );
  }

  if (sortKey) {
    result = result.slice().sort((a, b) => {
      if (a[sortKey] < b[sortKey]) return sortOrder === 'desc' ? 1 : -1;
      if (a[sortKey] > b[sortKey]) return sortOrder === 'desc' ? -1 : 1;
      return 0;
    });
  }

  return result;
}

