solution:
function createLatestOnlyLoader(fetcher) {
  let latestToken = 0;
  let state;

  return {
    load(...args) {
      const thisCallToken = ++latestToken;
      return fetcher(...args).then((value) => {
        const isStillLatest = thisCallToken === latestToken;
        if (isStillLatest) {
          state = value;
        }
        return { applied: isStillLatest, value };
      });
    },
    getState() {
      return state;
    }
  };
}
